BEGIN;
DO $$
DECLARE own uuid; lead uuid; member uuid; outsider uuid; p uuid; otherp uuid; t uuid; cover_task uuid; upload jsonb; cover_upload jsonb; d uuid; objectid uuid; blocked boolean; n integer;
BEGIN
 INSERT INTO public.st_members(auth_subject,display_name) VALUES('media-test-owner','媒体测试组长') RETURNING id INTO own;
 INSERT INTO public.st_members(auth_subject,display_name) VALUES('media-test-lead','媒体测试负责人') RETURNING id INTO lead;
 INSERT INTO public.st_members(auth_subject,display_name) VALUES('media-test-member','媒体测试成员') RETURNING id INTO member;
 INSERT INTO public.st_members(auth_subject,display_name) VALUES('media-test-outsider','媒体测试外部成员') RETURNING id INTO outsider;
 INSERT INTO public.st_member_roles(member_id,role_code) VALUES(own,'owner');
 PERFORM set_config('request.jwt.claim.sub','media-test-owner',true);
 p:=public.st_create_project('transaction-only-media-project','');otherp:=public.st_create_project('transaction-only-other-project','');
 PERFORM public.st_assign_member(p,lead,'lead');PERFORM public.st_assign_member(p,member,'contributor');
 t:=public.st_create_task(p,'transaction-only-video','test','clip');cover_task:=public.st_create_task(p,'transaction-only-cover','test','cover');
 PERFORM set_config('request.jwt.claim.sub','media-test-member',true);
 blocked:=false;BEGIN PERFORM public.st_delete_task(t,'transaction-only-video');EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Member task delete must fail';END IF;
 blocked:=false;BEGIN PERFORM public.st_delete_project(p,'transaction-only-media-project');EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Member project delete must fail';END IF;
 PERFORM set_config('request.jwt.claim.sub','media-test-lead',true);
 blocked:=false;BEGIN PERFORM public.st_delete_task(t,'wrong-name');EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Typed confirmation must be enforced';END IF;
 PERFORM public.st_delete_task(t,'transaction-only-video');
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(public.st_board(p)->'tasks') x WHERE x->>'id'=t::text) THEN RAISE EXCEPTION 'Deleted task must be hidden';END IF;
 blocked:=false;BEGIN PERFORM public.st_task_detail(t);EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Deleted task detail must be denied';END IF;
 PERFORM public.st_restore_task(t);
 blocked:=false;BEGIN PERFORM public.st_delete_project(otherp,'transaction-only-other-project');EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Lead cannot delete other projects';END IF;
 PERFORM set_config('request.jwt.claim.sub','media-test-owner',true);
 PERFORM public.st_claim_task(t);
 blocked:=false;BEGIN PERFORM public.st_submit(t,'subtitle text','manual','','');EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Video task cannot accept text';END IF;
 blocked:=false;BEGIN PERFORM public.st_upload_begin(t,'image.png','image/png',4,repeat('a',64));EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Video task rejects images';END IF;
 blocked:=false;BEGIN PERFORM public.st_upload_begin(t,'huge.mp4','video/mp4',1073741825,repeat('a',64));EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Video size limit failed';END IF;
 upload:=public.st_upload_begin(t,'video.mp4','video/mp4',4,repeat('a',64));
 IF NOT public.st_storage_write(upload->>'path') THEN RAISE EXCEPTION 'Reserved upload permission failed';END IF;
 blocked:=false;BEGIN PERFORM public.st_upload_finish((upload->>'id')::uuid,'test');EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Incomplete upload must not create a version';END IF;
 INSERT INTO storage.objects(bucket_id,name,owner_id,metadata) VALUES('subtitle-deliveries',upload->>'path','media-test-owner',jsonb_build_object('size',4,'mimetype','video/mp4','eTag','test-only')) RETURNING id INTO objectid;
 UPDATE storage.objects SET owner_id='media-test-outsider' WHERE id=objectid;
 blocked:=false;BEGIN PERFORM public.st_upload_finish((upload->>'id')::uuid,'wrong owner');EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Different nonempty owner must be rejected';END IF;
 UPDATE storage.objects SET owner_id='',created_at=now()-interval '1 day' WHERE id=objectid;
 blocked:=false;BEGIN PERFORM public.st_upload_finish((upload->>'id')::uuid,'old object');EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Object older than reservation must be rejected';END IF;
 UPDATE storage.objects SET created_at=now() WHERE id=objectid;
 d:=public.st_upload_finish((upload->>'id')::uuid,'metadata-only transactional test');
 IF public.st_upload_finish((upload->>'id')::uuid,'retry')<>d THEN RAISE EXCEPTION 'Upload completion idempotency failed';END IF;
 IF (SELECT count(*) FROM public.st_deliveries WHERE task_id=t)<>1 THEN RAISE EXCEPTION 'Upload must create exactly one version';END IF;
 IF public.st_storage_write(upload->>'path') THEN RAISE EXCEPTION 'Linked version cannot be overwritten';END IF;
 EXECUTE 'SET LOCAL ROLE authenticated';
 SELECT count(*) INTO n FROM storage.objects WHERE id=objectid;IF n<>1 THEN RAISE EXCEPTION 'Owner file read failed';END IF;
 UPDATE storage.objects SET metadata='{}'::jsonb WHERE id=objectid;GET DIAGNOSTICS n=ROW_COUNT;IF n<>0 THEN RAISE EXCEPTION 'Object overwrite must be denied';END IF;
 PERFORM set_config('request.jwt.claim.sub','media-test-member',true);
 SELECT count(*) INTO n FROM storage.objects WHERE id=objectid;IF n<>1 THEN RAISE EXCEPTION 'Project member file read failed';END IF;
 PERFORM set_config('request.jwt.claim.sub','media-test-outsider',true);
 SELECT count(*) INTO n FROM storage.objects WHERE id=objectid;IF n<>0 THEN RAISE EXCEPTION 'Cross-project file read must fail';END IF;
 EXECUTE 'SET LOCAL ROLE anon';
 SELECT count(*) INTO n FROM storage.objects WHERE id=objectid;IF n<>0 THEN RAISE EXCEPTION 'Anonymous file read must fail';END IF;
 EXECUTE 'RESET ROLE';
 PERFORM set_config('request.jwt.claim.sub','media-test-lead',true);
 PERFORM public.st_delete_project(p,'transaction-only-media-project');
 IF public.st_storage_read(upload->>'path') THEN RAISE EXCEPTION 'Deleted project files must be denied';END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.st_deleted_items(NULL)->'projects') x WHERE x->>'id'=p::text) THEN RAISE EXCEPTION 'Recycle bin visibility failed';END IF;
 PERFORM public.st_restore_project(p);
 IF NOT public.st_storage_read(upload->>'path') THEN RAISE EXCEPTION 'Restored project file access failed';END IF;
 PERFORM set_config('request.jwt.claim.sub','media-test-owner',true);
 PERFORM public.st_claim_task(cover_task);
 blocked:=false;BEGIN PERFORM public.st_upload_begin(cover_task,'video.mp4','video/mp4',4,repeat('a',64));EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Cover task rejects videos';END IF;
 blocked:=false;BEGIN PERFORM public.st_upload_begin(cover_task,'large.png','image/png',20971521,repeat('a',64));EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Cover size limit failed';END IF;
 cover_upload:=public.st_upload_begin(cover_task,'cover.png','image/png',4,repeat('b',64));
 IF cover_upload->>'mime_type'<>'image/png' THEN RAISE EXCEPTION 'Cover upload reservation failed';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.st_audit_events WHERE entity_table='st_projects' AND metadata->>'deleted_at' IS NOT NULL AND entity_id=p::text) THEN RAISE EXCEPTION 'Delete audit missing';END IF;
END; $$;
SELECT 'PASS: empty CloudBase owner compatibility; wrong owner and old object rejection; owner/lead-only soft deletion; typed confirmation; restoration; hidden deleted data; file type/size enforcement; upload finalization idempotency; immutable media; project-bound storage RLS; anonymous denial; delete audit. All fixtures including metadata rolled back, no physical files created.' AS verification;
ROLLBACK;
